import fs from 'node:fs';
import path from 'node:path';
import { PLATFORM_VERSION } from '../constants.js';
import { APP_FUNCTIONS_DIRNAME, APP_FUNCTIONS_MANIFEST_FILENAME, EXECUTION_TIMEOUT_MS, } from './constants.js';
import { ExecutionError, Reason } from './errors.js';
import { throwUnhandledPlatformVersionError } from './utils.js';
function loadMultiFunctionInfoLegacy(config) {
    const srcDir = path.join(config.app.path, APP_FUNCTIONS_DIRNAME);
    if (!fs.existsSync(srcDir)) {
        throw new Error(`Cannot locate app function directory: ${srcDir}`);
    }
    const stats = fs.lstatSync(srcDir);
    if (!stats.isDirectory()) {
        throw new Error(`Invalid app function directory: ${srcDir}`);
    }
    const manifestPath = path.join(srcDir, APP_FUNCTIONS_MANIFEST_FILENAME);
    const manifest = JSON.parse(fs.readFileSync(manifestPath, {
        encoding: 'utf-8',
    }));
    const { appFunctions = {} } = manifest;
    // TODO validation
    return { appFunctions, srcDir };
}
function loadMultiFunctionInfoUnified(config) {
    if (!config.appFunctions || Object.keys(config.appFunctions).length === 0) {
        throw new Error('No app function data provided. App function IR data is required for platform version 2026.03+.');
    }
    const appFunctions = {};
    for (const [uid, fnData] of Object.entries(config.appFunctions)) {
        appFunctions[uid] = {
            file: fnData.resolvedPath,
            secrets: fnData.secrets,
        };
    }
    // Use componentRoot (the directory containing hsmeta.json) as srcDir.
    // This is where the .env file lives, not necessarily where the entrypoint resolves to.
    const srcDir = Object.values(config.appFunctions)[0].componentRoot;
    return { appFunctions, srcDir };
}
export function loadMultiFunctionInfo(config) {
    switch (config.platformVersion) {
        case PLATFORM_VERSION.V20251:
            return loadMultiFunctionInfoLegacy(config);
        case PLATFORM_VERSION.V202603:
        case PLATFORM_VERSION.V202603BETA:
        case PLATFORM_VERSION.V202609:
        case PLATFORM_VERSION.V202609BETA:
        case PLATFORM_VERSION.V202703:
        case PLATFORM_VERSION.V202703BETA:
        case PLATFORM_VERSION.UNSTABLE:
            return loadMultiFunctionInfoUnified(config);
        case PLATFORM_VERSION.V20252:
            // We shouldn't run into this specific case due to earlier throwing but we need it just in case an app gets in a weird state.
            throw new ExecutionError({
                reason: Reason.UnsupportedVersion,
                functionName: 'unknown',
            });
        default:
            return throwUnhandledPlatformVersionError(config.platformVersion);
    }
}
export function loadFunctionInfo(config, functionName, appId) {
    const { logger } = config;
    const { appFunctions, srcDir } = loadMultiFunctionInfo(config);
    const metadata = appFunctions[functionName];
    if (!metadata) {
        const availableFunctions = Object.keys(appFunctions);
        const availableFunctionsSuffix = availableFunctions.length > 0
            ? `Available functions: [${availableFunctions.join(', ')}]`
            : 'Available functions: [] (no app functions are currently declared in this project).';
        const isLegacy = config.platformVersion === PLATFORM_VERSION.V20251;
        const message = isLegacy
            ? `App function "${functionName}" was not found in ${path.join(srcDir, APP_FUNCTIONS_MANIFEST_FILENAME)}. ${availableFunctionsSuffix}`
            : `App function "${functionName}" was not found. Declare it by adding an *-hsmeta.json file with "type": "app-function" and "uid": "${functionName}" under the functions component directory. Refer to the documentation for more details:\nhttps://developers.hubspot.com/docs/apps/developer-platform/add-features/serverless-functions/reference#function-configuration\n\n${availableFunctionsSuffix}`;
        logger.error(message);
        throw new ExecutionError({
            reason: Reason.FunctionNotFound,
            functionName,
            appId,
        });
    }
    // TODO validation
    return { ...metadata, srcDir, name: functionName };
}
export function buildServiceConfiguration(appPath, options) {
    return {
        accountId: options.accountId,
        app: { path: appPath },
        functionTimeoutMs: options.functionTimeoutMs ?? EXECUTION_TIMEOUT_MS,
        hubspotApiOrigin: options.hubspotApiOrigin,
        hubspotWebsiteOrigin: options.hubspotWebsiteOrigin,
        logger: options.logger ?? console,
        platformVersion: options.platformVersion ?? PLATFORM_VERSION.V20251,
        appFunctions: options.appFunctions,
    };
}
